From 8cd27d6c0f0fbb811521350c83db32b4bb7a95c7 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 20:09:03 +0100
Subject: [PATCH] containments/desktop: don't drop icons under desktop widgets

Icons and widgets live on separate layers, so an icon could be dropped
under a widget, where it can't be seen or clicked anymore. Dropping an
icon on a widget now puts it in the nearest free cell next to it instead.

BUG: 519851
---
 .../package/contents/ui/FolderView.qml        | 69 +++++++++++++++++++
 1 file changed, 69 insertions(+)

diff --git a/containments/desktop/package/contents/ui/FolderView.qml b/containments/desktop/package/contents/ui/FolderView.qml
index b858d16f7a..7c59817486 100644
--- a/containments/desktop/package/contents/ui/FolderView.qml
+++ b/containments/desktop/package/contents/ui/FolderView.qml
@@ -702,6 +702,73 @@ FocusScope {
                     return -1
                 }

+                function cellPosition(stripe, pos) {
+                    const rows = (flow === GridView.FlowLeftToRight);
+                    const column = rows ? pos : stripe;
+                    let x = column * cellWidth;
+                    if (effectiveLayoutDirection === Qt.RightToLeft) {
+                        x = rows ? contentX + width - x - cellWidth : originX + contentItem.width - x - cellWidth;
+                    }
+                    return Qt.point(x, (rows ? stripe : pos) * cellHeight);
+                }
+
+                // Whether an item laid out like delegate would overlap a widget when placed in the given cell.
+                function cellCoveredByWidget(stripe, pos, delegate) {
+                    const layout = root.appletsLayout;
+                    if (!root.isContainment || !layout) {
+                        return false;
+                    }
+                    let rect = Qt.rect(0, 0, cellWidth, cellHeight);
+                    if (delegate && delegate.iconArea && delegate.labelArea) {
+                        const icon = delegate.iconArea.mapToItem(delegate, 0, 0, delegate.iconArea.width, delegate.iconArea.height);
+                        const label = delegate.labelArea.mapToItem(delegate, 0, 0, delegate.labelArea.width, delegate.labelArea.height);
+                        const left = Math.min(icon.x, label.x);
+                        const top = Math.min(icon.y, label.y);
+                        rect = Qt.rect(left, top, Math.max(icon.x + icon.width, label.x + label.width) - left,
+                                       Math.max(icon.y + icon.height, label.y + label.height) - top);
+                    }
+                    const origin = cellPosition(stripe, pos);
+                    const mapped = contentItem.mapToItem(layout, origin.x + rect.x, origin.y + rect.y, rect.width, rect.height);
+                    const left = Math.max(mapped.x, 0) + 1;
+                    const top = Math.max(mapped.y, 0) + 1;
+                    const right = Math.min(mapped.x + mapped.width, layout.width) - 1;
+                    const bottom = Math.min(mapped.y + mapped.height, layout.height) - 1;
+                    if (right <= left || bottom <= top) {
+                        return false;
+                    }
+                    return !layout.isRectAvailable(left, top, right - left, bottom - top);
+                }
+
+                // The free cell nearest to the given one where the dragged item would not end up under a widget.
+                function nearestCellFreeOfWidgets(from, to, taken) {
+                    const perStripe = positioner.perStripe;
+                    const delegate = itemAtIndex(from);
+                    const stripe = Math.floor(to / perStripe);
+                    const pos = to % perStripe;
+                    if (!cellCoveredByWidget(stripe, pos, delegate)) {
+                        return to;
+                    }
+                    const target = cellPosition(stripe, pos);
+                    const stripes = Math.max(positioner.optimalStripes, Math.ceil(positioner.rowCount() / perStripe));
+                    let best = to;
+                    let bestDistance = Infinity;
+                    for (let s = 0; s < stripes; s++) {
+                        for (let p = 0; p < perStripe; p++) {
+                            const index = (s * perStripe) + p;
+                            if ((index !== from && !positioner.isBlank(index)) || taken.includes(index)) {
+                                continue;
+                            }
+                            const point = cellPosition(s, p);
+                            const distance = Math.hypot(point.x - target.x, point.y - target.y);
+                            if (distance < bestDistance && !cellCoveredByWidget(s, p, delegate)) {
+                                best = index;
+                                bestDistance = distance;
+                            }
+                        }
+                    }
+                    return best;
+                }
+
                 PlasmaComponents.ScrollBar.vertical: PlasmaComponents.ScrollBar {
                     id: verticalScrollBar
                 }
@@ -1315,6 +1382,8 @@ FocusScope {
                         if (to < 0) {
                             return;
                         }
+
+                        to = gridView.nearestCellFreeOfWidgets(from, to, moves.filter((_, j) => j % 2 === 1));
                     }

                     if (from !== to) {
